// Compiles content/*.md into js/content.js (a plain script, so the app also
// works when opened straight from disk without a server).
//   node scripts/build-content.mjs
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseAll } from "./content-parser.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const data = parseAll(join(root, "content"));
const js =
  "/* Generated by scripts/build-content.mjs from content/*.md. Edit those files, not this one. */\n" +
  "window.CODLE_CONTENT = " + JSON.stringify(data, null, 1) + ";\n";
writeFileSync(join(root, "js/content.js"), js);
const counts = data.map((l) => `${l.name}: ${l.lessons.length} lessons, ${l.quiz.length} questions, ${l.challenges.length} challenges`);
console.log("Wrote js/content.js\n  " + counts.join("\n  "));
